# Appendix Table A.6: whole-task versus subtask-based scores. Run from anywhere:
#   python3 code/tables/tabB-whole-task.py      (writes output/tables/tabB-whole-task.tex)
# Inputs: the comparison CSVs (data/scoring/whole_task_*.csv) written by the scoring project's robustness/compare_whole_task.py for the full run
# (19,281 tasks, three models) and the pilot retest (Gemini, 1,000 tasks).
import sys as _sys, pathlib as _pl; _sys.path.insert(0, str(_pl.Path(__file__).resolve().parents[1])); from paths import *   # repository-relative paths (code/paths.py)
import pandas as pd
R=str(SCORING)   # data/scoring/
lev=pd.read_csv(f"{R}/whole_task_full_levels.csv"); agr=pd.read_csv(f"{R}/whole_task_full_agreement.csv")
bn=pd.read_csv(f"{R}/whole_task_full_bunching.csv"); xr=pd.read_csv(f"{R}/whole_task_full_crossrater.csv")
rt=pd.read_csv(f"{R}/whole_task_pilot1000_retest.csv"); ad=pd.read_csv(f"{R}/whole_task_adoption.csv")
raters=["Claude Haiku 4.5","GPT-5.6-luna","Gemini 3.1 Flash-Lite"]
def g(df,**k):
    d=df
    for a,b in k.items(): d=d[d[a]==b]
    return d.iloc[0]
L=["% Appendix Table A.6: whole-task versus subtask-based scores. Generated by code/tables/tabB-whole-task.py",
   "% from the whole-task comparison files (data/scoring/whole_task_*.csv). Do not edit by hand.",
   "\\begin{table}[htbp]\n\\centering\n\\begin{threeparttable}\n\\caption{Scoring the task as a whole versus scoring its subtasks}\n\\label{tab:wholetask}\n\\footnotesize\\setlength{\\tabcolsep}{5pt}\n\\begin{spacing}{1}\n\\begin{tabular}{@{}lrrrr@{}}\n\\toprule",
   " & Claude Haiku 4.5 & GPT-5.6-luna & Gemini 3.1 Flash-Lite & Three-model average \\\\\n\\midrule",
   "\\multicolumn{5}{@{}l}{\\emph{Mean exposure score at stage 4}} \\\\"]
L.append("Subtask-based & "+" & ".join(f"{g(lev,rater=r,stage=4).subtask_mean:.1f}" for r in raters)+" & -- \\\\")
L.append("Whole task & "+" & ".join(f"{g(lev,rater=r,stage=4).whole_mean:.1f}" for r in raters)+" & -- \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Rank correlation between the two methods, same model}} \\\\")
L.append("Stage-4 level & "+" & ".join(f"{g(agr,rater=r,measure='composite s4').spearman:.2f}" for r in raters)+" & -- \\\\")
L.append("Change, stage 1 to 4 & "+" & ".join(f"{g(agr,rater=r,measure='change s1 to s4').spearman:.2f}" for r in raters)+" & -- \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Distinct values of the time-saved rating at stage 4}} \\\\")
L.append("Subtask-based & "+" & ".join(f"{int(g(bn,rater=r,component='time saved (feasible)',method='subtask-based').distinct)}" for r in raters)+" & -- \\\\")
L.append("Whole task & "+" & ".join(f"{int(g(bn,rater=r,component='time saved (feasible)',method='whole task').distinct)}" for r in raters)+" & -- \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Rank correlation of the stage-1 to stage-4 change with the other two models, average}} \\\\")
def xavg(method,r):
    rows=xr[(xr.measure=="change s1 to s4")&(xr.pair.str.contains(r,regex=False))]; return rows[f"{method}_spearman"].mean()
L.append("Subtask-based & "+" & ".join(f"{xavg('subtask',r):.2f}" for r in raters)+" & -- \\\\")
L.append("Whole task & "+" & ".join(f"{xavg('whole',r):.2f}" for r in raters)+" & -- \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Correlation with adoption across 141 occupations, change from stage 1 to 3}} \\\\")
AD={"Claude Haiku 4.5":"claude-haiku-4.5","GPT-5.6-luna":"gpt-luna","Gemini 3.1 Flash-Lite":"gemini-flash-lite"}
L.append("Subtask-based & "+" & ".join(f"{g(ad,rater=AD[r],measure='change s1 to s3').subtask_based:.2f}" for r in raters)+f" & {g(ad,rater='Three-rater average',measure='change s1 to s3').subtask_based:.2f} \\\\")
L.append("Whole task & "+" & ".join(f"{g(ad,rater=AD[r],measure='change s1 to s3').whole_task:.2f}" for r in raters)+f" & {g(ad,rater='Three-rater average',measure='change s1 to s3').whole_task:.2f} \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Correlation with adoption across 141 occupations, change from stage 1 to 4}} \\\\")
L.append("Subtask-based & "+" & ".join(f"{g(ad,rater=AD[r],measure='change s1 to s4').subtask_based:.2f}" for r in raters)+f" & {g(ad,rater='Three-rater average',measure='change s1 to s4').subtask_based:.2f} \\\\")
L.append("Whole task & "+" & ".join(f"{g(ad,rater=AD[r],measure='change s1 to s4').whole_task:.2f}" for r in raters)+f" & {g(ad,rater='Three-rater average',measure='change s1 to s4').whole_task:.2f} \\\\")
L.append("\\addlinespace\n\\multicolumn{5}{@{}l}{\\emph{Test-retest rank correlation of the time-saved rating at stage 4, 1,000-task pilot}} \\\\")
sub=g(rt,rater="Gemini 3.1 Flash-Lite",method="subtask-based",measure="time saved (feasible) s4").retest_spearman
who=g(rt,rater="Gemini 3.1 Flash-Lite",method="whole task",measure="time saved (feasible) s4").retest_spearman
L.append(f"Subtask-based & -- & -- & {sub:.2f} & -- \\\\\nWhole task & -- & -- & {who:.2f} & -- \\\\")
L.append("\\bottomrule\n\\end{tabular}\n\\end{spacing}\n\\begin{tablenotes}\\notesize\n\\item Notes: Each model scored all 19,281 O*NET tasks twice: once subtask by subtask with the fixed decomposition and the three prompts of Section 2, and once as a whole, with the task statement alone and the same three questions asked as percentages of the task, using the same stage definitions, typology, and monotonicity rules. Whole-task scores were obtained through OpenRouter on October 8, 2026, at temperature zero. The composite is the same average of the three ratings in both cases. Correlations are across tasks. The adoption rows aggregate each score to census occupations as in Section 2 and correlate the change with the share of workers using generative AI at work in the Real-Time Population Survey, weighted by respondents, for the 141 occupations with at least 20 respondents. The test-retest rows repeat the 1,000-task pilot sample a second time with the same settings for one model.\n\\end{tablenotes}\n\\end{threeparttable}\n\\end{table}")
open(TABLES/"tabB-whole-task.tex","w").write("\n".join(L)+"\n"); print("\n".join(L[4:-1]))
